from html import escape
def make_html_report(r):
 f=''.join(f"<tr><td>{escape(x['severity'])}</td><td>{escape(x['type'])}</td><td>{escape(x['message'])}</td></tr>" for x in r['findings'])
 i=''.join(f"<tr><td>{x['type']}</td><td>{escape(x['value'])}</td></tr>" for x in r['iocs'])
 g=''.join(f"<tr><td>{x['ip']}</td><td>{x['country']}</td><td>{x['city']}</td><td>{x['isp']}</td></tr>" for x in r['geo'])
 return f'''<html><head><meta charset="utf-8"><title>SentinelAI Forensic Report</title><style>body{{font-family:Arial;margin:40px;color:#172033}}.hero{{background:#121827;color:white;padding:24px;border-radius:14px}}table{{width:100%;border-collapse:collapse;margin:16px 0}}td,th{{border:1px solid #ddd;padding:9px;text-align:left}}</style></head><body><div class="hero"><h1>SentinelAI — Email Forensic Report</h1><h2>{r['risk_score']}/100 — {r['severity']}</h2><p>{escape(r['ml']['label'])} • {r['ml']['confidence']*100:.0f}% confidence</p></div><h2>Email</h2><p><b>Subject:</b> {escape(r['subject'])}</p><p><b>From:</b> {escape(r['sender'])}</p><p><b>Reply-To:</b> {escape(r['reply_to'])}</p><h2>Authentication</h2><p>SPF {r['authentication']['spf']} | DKIM {r['authentication']['dkim']} | DMARC {r['authentication']['dmarc']}</p><h2>Findings</h2><table><tr><th>Severity</th><th>Type</th><th>Evidence</th></tr>{f}</table><h2>IOC Inventory</h2><table><tr><th>Type</th><th>Value</th></tr>{i}</table><h2>IP Intelligence</h2><table><tr><th>IP</th><th>Country</th><th>City</th><th>ISP</th></tr>{g}</table><h2>Attachments</h2><p>{', '.join(a['name']+' — '+a['sha256'] for a in r['attachments']) or 'None'}</p><p><b>Recommendation:</b> {escape(r['recommendation'])}</p></body></html>'''
